<script setup>
import {ref,computed,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,errorText} from '../services/api.js';import {useAuth} from '../stores/auth.js';
const route=useRoute(),router=useRouter(),auth=useAuth(),id=route.params.id;const trip=ref(null),expenses=ref([]),payments=ref([]),summary=ref({totalCents:0,expenseCount:0,balances:[],transfers:[]});const tab=ref('expenses'),error=ref(''),success=ref(''),dialog=ref(false),payDialog=ref(false),mode=ref('equal'),busy=ref(false);const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};const displayDate=iso=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso||'');return m?`${m[3]}/${m[2]}/${m[1]}`:'';};const parseDate=text=>{const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(text||'');if(!m)return null;const [_,dd,mm,yyyy]=m;const d=new Date(Date.UTC(+yyyy,+mm-1,+dd));return d.getUTCFullYear()===+yyyy&&d.getUTCMonth()===+mm-1&&d.getUTCDate()===+dd?`${yyyy}-${mm}-${dd}`:null;};const form=ref({title:'',date:today(),amount:'',paidBy:'',participants:[],custom:{}}),pay=ref({from:'',to:'',amount:'',note:''});
const editTripDialog=ref(false),editTripBusy=ref(false),editTripError=ref('');
const tripEdit=ref({name:'',description:''});
function openEditTrip(){if(!isOwner.value)return;tripEdit.value={name:trip.value?.name||'',description:trip.value?.description||''};editTripError.value='';editTripDialog.value=true;}
async function saveTrip(){
  const name=tripEdit.value.name.trim(),description=tripEdit.value.description.trim();
  if(!name||name.length>120||description.length>500){editTripError.value='กรุณากรอกชื่อทริป (ไม่เกิน 120 ตัวอักษร) และรายละเอียดไม่เกิน 500 ตัวอักษร';return;}
  editTripBusy.value=true;editTripError.value='';
  try{const {data}=await api.patch('/trips/'+id,{name,description});trip.value=data;editTripDialog.value=false;success.value='แก้ไขข้อมูลทริปเรียบร้อยแล้ว';}
  catch(e){editTripError.value=errorText(e);}finally{editTripBusy.value=false;}
}
const dateInput=ref(displayDate(today()));const logs=ref([]),logPage=ref(1),logTotal=ref(0),logLoading=ref(false);const bankDialog=ref(false),bankEditId=ref(null),bankForm=ref({bank:'',accountName:'',accountNumber:'',isDefault:false});const members=computed(()=>trip.value?.members||[]),names=computed(()=>Object.fromEntries(members.value.map(m=>[m._id,m.name]))),isOwner=computed(()=>trip.value?.owner===auth.user?.id);const memberById=u=>members.value.find(m=>m._id===u);const primaryAccount=u=>memberById(u)?.bankAccounts?.find(a=>a.isDefault)||memberById(u)?.bankAccounts?.[0];const myAccounts=computed(()=>memberById(auth.user?.id)?.bankAccounts||[]);const thb=c=>(Number(c||0)/100).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});const cents=v=>Math.round(Number(v)*100);const amountValid=v=>Number.isFinite(Number(v))&&Number(v)>0&&Number.isSafeInteger(cents(v));
async function load(){try{const [t,e,p,s]=await Promise.all([api.get('/trips/'+id),api.get('/trips/'+id+'/expenses'),api.get('/trips/'+id+'/payments'),api.get('/trips/'+id+'/summary')]);trip.value=t.data;expenses.value=e.data;payments.value=p.data;summary.value=s.data;}catch(e){error.value=errorText(e);if(e.response?.status===401){auth.logout();router.push('/login');}}}
async function loadLogs(page=1){logLoading.value=true;try{const {data}=await api.get('/trips/'+id+'/logs',{params:{page,limit:30}});logs.value=data.items;logTotal.value=data.total;logPage.value=data.page;}catch(e){error.value=errorText(e);}finally{logLoading.value=false;}}
const actionLabels={"trip.created":"สร้างทริป","member.joined":"เข้าร่วมทริป","member.removed":"ลบสมาชิก","expense.created":"เพิ่มค่าใช้จ่าย","expense.deleted":"ลบค่าใช้จ่าย","payment.created":"บันทึกการโอน","payment.deleted":"ลบประวัติการโอน","bank.created":"เพิ่มบัญชีธนาคาร","bank.updated":"แก้ไขบัญชีธนาคาร","bank.deleted":"ลบบัญชีธนาคาร","profile.name.updated":"เปลี่ยนชื่อผู้ใช้งาน"};
function openExpense(){form.value={title:'',date:today(),amount:'',paidBy:auth.user?.id||members.value[0]?._id,participants:members.value.map(m=>m._id),custom:{}};dateInput.value=displayDate(today());mode.value='equal';dialog.value=true;}
async function saveExpense(){error.value='';if(!amountValid(form.value.amount)){error.value='กรุณากรอกจำนวนเงินที่ถูกต้อง';return;}const isoDate=parseDate(dateInput.value);if(!isoDate){error.value='กรุณาระบุวันที่เป็น วัน/เดือน/ปี เช่น 03/11/2026';return;}if(!form.value.participants.length){error.value='กรุณาเลือกผู้ร่วมรับผิดชอบอย่างน้อย 1 คน';return;}const payload={title:form.value.title,date:isoDate,amountCents:cents(form.value.amount),paidBy:form.value.paidBy};if(mode.value==='equal'){payload.participants=form.value.participants;}else{payload.splits=members.value.filter(m=>form.value.participants.includes(m._id)).map(m=>({user:m._id,amountCents:Math.round(Number(form.value.custom[m._id]||0)*100)}));}busy.value=true;try{await api.post('/trips/'+id+'/expenses',payload);dialog.value=false;await load();success.value='บันทึกรายการแล้ว';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function removeExpense(e){if(!confirm('ยืนยันลบรายการ '+e.title+'?'))return;try{await api.delete('/trips/'+id+'/expenses/'+e._id);await load();}catch(err){error.value=errorText(err);}}
function openBank(a=null){bankEditId.value=a?._id||null;bankForm.value=a?{bank:a.bank,accountName:a.accountName,accountNumber:a.accountNumber,isDefault:!!a.isDefault}:{bank:'',accountName:auth.user?.name||'',accountNumber:'',isDefault:!myAccounts.value.length};bankDialog.value=true;}
async function saveBank(){error.value='';busy.value=true;try{const url='/auth/me/bank-accounts'+(bankEditId.value?'/'+bankEditId.value:'');await (bankEditId.value?api.put(url,bankForm.value):api.post(url,bankForm.value));bankDialog.value=false;await load();success.value='บันทึกบัญชีธนาคารแล้ว';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function removeBank(a){if(!confirm('ลบบัญชีธนาคารนี้?'))return;try{await api.delete('/auth/me/bank-accounts/'+a._id);await load();success.value='ลบบัญชีแล้ว';}catch(e){error.value=errorText(e);}}
function openPay(t){pay.value={from:t.from,to:t.to,amount:(t.amountCents/100).toFixed(2),note:''};payDialog.value=true;}
async function savePayment(){error.value='';if(!amountValid(pay.value.amount)){error.value='กรุณากรอกยอดโอนที่ถูกต้อง';return;}busy.value=true;try{await api.post('/trips/'+id+'/payments',{from:pay.value.from,to:pay.value.to,amountCents:cents(pay.value.amount),note:pay.value.note});payDialog.value=false;await load();success.value='บันทึกการชำระเงินแล้ว';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function removePayment(p){if(!confirm('ยืนยันลบประวัติการโอน?'))return;try{await api.delete('/trips/'+id+'/payments/'+p._id);await load();}catch(e){error.value=errorText(e);}}
async function removeMember(m){if(!confirm('ลบสมาชิก '+m.name+'?'))return;try{await api.delete('/trips/'+id+'/members/'+m._id);await load();}catch(e){error.value=errorText(e);}}
async function copyCode(){try{await navigator.clipboard.writeText(trip.value.joinCode);success.value='คัดลอกรหัสเชิญแล้ว';}catch{error.value='ไม่สามารถคัดลอกอัตโนมัติได้';}}
function exportCsv(){const rows=[['วันที่','รายการ','จำนวนเงิน','ผู้จ่าย','ผู้ร่วมรับผิดชอบ','ยอดหารรายคน'],...expenses.value.map(e=>[new Date(e.date).toLocaleDateString('en-GB'),e.title,(e.amountCents/100).toFixed(2),names.value[e.paidBy],e.splits.map(s=>names.value[s.user]).join(' / '),e.splits.map(s=>names.value[s.user]+': '+thb(s.amountCents)).join(' / ')])];const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='splittrip-expenses.csv';a.click();URL.revokeObjectURL(url);}
const expenseSearch=ref('');
const filteredExpenses=computed(()=>{const q=expenseSearch.value.trim().toLocaleLowerCase();return q?expenses.value.filter(e=>(e.title||'').toLocaleLowerCase().includes(q)||(names.value[e.paidBy]||'').toLocaleLowerCase().includes(q)):expenses.value;});
const expandedExpenses=ref([]);
function toggleSplitDetails(expenseId){expandedExpenses.value=expandedExpenses.value.includes(expenseId)?expandedExpenses.value.filter(x=>x!==expenseId):[...expandedExpenses.value,expenseId];}
function splitInitial(userId){return (names.value[userId]||'?').trim().slice(0,1).toUpperCase();}
function isEqualSplit(e){const splits=e.splits||[];return splits.length>0&&Math.max(...splits.map(s=>s.amountCents))-Math.min(...splits.map(s=>s.amountCents))<=1;}
function averageSplit(e){return Math.round(e.amountCents/(e.splits?.length||1));}
onMounted(load);
</script>
<template><v-container class="page py-7"><v-btn variant="text" prepend-icon="mdi-arrow-left" class="mb-3" @click="router.push('/')">ทริปทั้งหมด</v-btn><v-alert v-if="error" type="error" variant="tonal" closable class="mb-4" @click:close="error=''">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" closable class="mb-4" @click:close="success=''">{{success}}</v-alert><template v-if="trip"><div class="d-flex align-center flex-wrap ga-3 mb-6"><div><div class="d-flex align-center ga-2"><h1 class="text-h4 font-weight-bold">{{trip.name}}</h1><v-btn v-if="isOwner" icon="mdi-pencil-outline" variant="tonal" color="primary" size="small" aria-label="แก้ไขชื่อและรายละเอียดทริป" title="แก้ไขชื่อและรายละเอียดทริป" @click="openEditTrip"/></div><p class="muted">{{trip.description||'ค่าใช้จ่ายร่วมกันของทริป'}} · {{members.length}} สมาชิก</p></div><v-spacer/><v-btn variant="outlined" prepend-icon="mdi-file-export" @click="exportCsv">Export CSV</v-btn><v-btn color="primary" prepend-icon="mdi-plus" @click="openExpense">เพิ่มค่าใช้จ่าย</v-btn></div><v-row class="mb-5"><v-col cols="12" sm="4"><v-card class="soft-card pa-5" elevation="0"><div class="muted">ค่าใช้จ่ายรวม</div><div class="text-h4 font-weight-bold money">฿{{thb(summary.totalCents)}}</div></v-card></v-col><v-col cols="6" sm="4"><v-card class="soft-card pa-5" elevation="0"><div class="muted">จำนวนรายการ</div><div class="text-h4 font-weight-bold">{{summary.expenseCount}}</div></v-card></v-col><v-col cols="6" sm="4"><v-card class="soft-card pa-5" elevation="0"><div class="muted">สมาชิก</div><div class="text-h4 font-weight-bold">{{members.length}}</div></v-card></v-col></v-row><v-card class="soft-card mb-6 pa-4" elevation="0"><div class="d-flex align-center flex-wrap ga-3"><v-icon color="primary">mdi-account-multiple-plus</v-icon><strong>รหัสเชิญเพื่อนเข้าทริป:</strong><v-chip color="primary" variant="tonal" size="large">{{trip.joinCode}}</v-chip><v-btn size="small" variant="text" @click="copyCode()">คัดลอก</v-btn><span class="muted text-body-2">ให้เพื่อนสมัครบัญชีแล้วกรอกรหัสนี้</span></div></v-card><v-card class="soft-card" elevation="0"><v-tabs v-model="tab" color="primary"><v-tab value="expenses">รายการค่าใช้จ่าย</v-tab><v-tab value="summary">สรุปยอด / โอนคืน</v-tab><v-tab value="members">สมาชิก</v-tab><v-tab value="logs" @click="loadLogs(1)">ประวัติการทำรายการ</v-tab></v-tabs><v-divider/><v-window v-model="tab"><v-window-item value="expenses">
  <div class="expense-toolbar">
    <div><strong>รายการค่าใช้จ่าย</strong><span class="muted ml-2 text-caption">{{expenses.length}} รายการ</span></div>
    <v-text-field v-model="expenseSearch" density="compact" variant="outlined" hide-details clearable placeholder="ค้นหารายการหรือผู้จ่าย" prepend-inner-icon="mdi-magnify" class="expense-search" />
  </div>
  <div class="expense-table-wrap">
    <table class="expense-table">
      <thead><tr><th>วันที่</th><th>รายการ</th><th class="amount-col">จำนวนเงิน</th><th>ผู้จ่าย</th><th>หารกับ</th><th class="action-col">จัดการ</th></tr></thead>
      <tbody>
        <template v-for="e in filteredExpenses" :key="e._id">
          <tr class="expense-row">
            <td class="date-col">{{new Date(e.date).toLocaleDateString('en-GB')}}</td>
            <td><div class="expense-title">{{e.title}}</div></td>
            <td class="amount-col"><strong>฿{{thb(e.amountCents)}}</strong></td>
            <td><div class="payer"><span class="payer-avatar">{{splitInitial(e.paidBy)}}</span><span class="payer-name">{{names[e.paidBy]||'สมาชิก'}}</span></div></td>
            <td>
              <button class="split-compact" type="button" :aria-expanded="expandedExpenses.includes(e._id)" :aria-label="'ดูรายละเอียดการหารของ '+e.title" @click="toggleSplitDetails(e._id)">
                <span class="split-stack"><span v-for="(s,i) in (e.splits||[]).slice(0,3)" :key="s.user" class="split-avatar" :class="'split-avatar-'+(i%4)" :title="names[s.user]">{{splitInitial(s.user)}}</span><span v-if="(e.splits||[]).length>3" class="split-overflow">+{{e.splits.length-3}}</span></span>
                <span class="split-caption"><strong>{{e.splits?.length||0}} คน</strong><small>{{isEqualSplit(e)?'เฉลี่ย ฿'+thb(averageSplit(e)):'หารตามยอด'}}</small></span>
                <v-icon size="18" color="primary">{{expandedExpenses.includes(e._id)?'mdi-chevron-up':'mdi-chevron-down'}}</v-icon>
              </button>
            </td>
            <td class="action-col"><v-btn icon="mdi-delete-outline" size="small" variant="text" color="error" :aria-label="'ลบรายการ '+e.title" @click="removeExpense(e)" /></td>
          </tr>
          <tr v-if="expandedExpenses.includes(e._id)" class="details-row"><td colspan="6"><div class="split-detail-panel">
            <div class="detail-head"><strong>รายละเอียดการหาร · {{e.title}}</strong><span>{{e.splits?.length||0}} คน</span></div>
            <div class="detail-grid"><div v-for="(s,i) in (e.splits||[])" :key="s.user" class="detail-member"><span class="split-avatar" :class="'split-avatar-'+(i%4)">{{splitInitial(s.user)}}</span><span class="detail-name">{{names[s.user]||'สมาชิก'}}</span><strong>฿{{thb(s.amountCents)}}</strong></div></div>
            <div class="detail-foot"><span>รวมยอดที่รับผิดชอบ</span><strong>฿{{thb((e.splits||[]).reduce((sum,s)=>sum+s.amountCents,0))}}</strong></div>
          </div></td></tr>
        </template>
        <tr v-if="!filteredExpenses.length"><td colspan="6" class="empty-expenses">{{expenses.length?'ไม่พบรายการที่ค้นหา':'ยังไม่มีค่าใช้จ่ายในทริปนี้'}}</td></tr>
      </tbody>
    </table>
  </div>
</v-window-item><v-window-item value="summary"><v-row class="pa-4"><v-col cols="12" md="6"><h3 class="text-h6 mb-3">ยอดสุทธิรายคน</h3><v-list><v-list-item v-for="b in summary.balances" :key="b.user" :title="names[b.user]"><template #append><strong :class="b.balanceCents>=0?'text-success':'text-error'">{{b.balanceCents>=0?'+':'−'}}฿{{thb(Math.abs(b.balanceCents))}}</strong></template></v-list-item></v-list><p class="muted text-caption mt-2">บวก = ควรได้รับคืน / ลบ = ต้องจ่ายเพิ่ม (หลังหักยอดที่โอนแล้ว)</p></v-col><v-col cols="12" md="6"><h3 class="text-h6 mb-3">รายการโอนที่แนะนำ</h3><v-card v-for="(t,i) in summary.transfers" :key="i" class="pa-3 mb-2" variant="outlined"><div class="d-flex align-center flex-wrap ga-2"><strong>{{names[t.from]}}</strong><v-icon>mdi-arrow-right</v-icon><strong>{{names[t.to]}}</strong><v-spacer/><strong class="text-primary">฿{{thb(t.amountCents)}}</strong><div v-if="primaryAccount(t.to)" class="text-caption">รับเงิน: {{primaryAccount(t.to).bank}} · {{primaryAccount(t.to).accountName}} · {{primaryAccount(t.to).accountNumber}}</div><v-btn v-if="t.from===auth.user?.id||isOwner" size="small" color="primary" variant="tonal" @click="openPay(t)">บันทึกโอน</v-btn></div></v-card><p v-if="!summary.transfers.length" class="muted">ทุกคนเคลียร์ยอดแล้ว หรือยังไม่มีค่าใช้จ่าย</p></v-col></v-row><v-divider/><div class="pa-4"><h3 class="text-h6 mb-3">ประวัติการชำระเงิน</h3><v-list><v-list-item v-for="p in payments" :key="p._id" :title="`${names[p.from]} → ${names[p.to]}`" :subtitle="new Date(p.createdAt).toLocaleString('th-TH')+(p.note?' · '+p.note:'')"><template #append><strong class="mr-3">฿{{thb(p.amountCents)}}</strong><v-btn v-if="p.createdBy===auth.user?.id||isOwner" icon="mdi-delete-outline" variant="text" size="small" color="error" @click="removePayment(p)"/></template></v-list-item><p v-if="!payments.length" class="muted">ยังไม่มีประวัติการโอน</p></v-list></div></v-window-item><v-window-item value="members"><div class="d-flex align-center justify-space-between pa-4"><strong>บัญชีธนาคารสำหรับรับเงินคืน</strong><v-btn color="primary" size="small" prepend-icon="mdi-plus" @click="openBank()">เพิ่มบัญชีของฉัน</v-btn></div><v-list><v-list-item v-for="m in members" :key="m._id" :title="m.name" :subtitle="m.email"><div v-for="a in (m.bankAccounts||[])" :key="a._id" class="text-caption my-1">{{a.bank}} · {{a.accountName}} · {{a.accountNumber}} <v-chip v-if="a.isDefault" size="x-small" color="primary">บัญชีหลัก</v-chip><v-btn v-if="m._id===auth.user?.id" size="x-small" variant="text" @click="openBank(a)">แก้ไข</v-btn><v-btn v-if="m._id===auth.user?.id" size="x-small" color="error" variant="text" @click="removeBank(a)">ลบ</v-btn></div><template #append><v-chip v-if="m._id===trip.owner" size="small" color="primary">เจ้าของทริป</v-chip><v-btn v-else-if="isOwner" icon="mdi-account-remove-outline" variant="text" color="error" @click="removeMember(m)"/></template></v-list-item></v-list></v-window-item><v-window-item value="logs"><div class="pa-4"><div class="d-flex align-center justify-space-between mb-3"><h3 class="text-h6">ประวัติการบันทึกข้อมูล</h3><v-btn variant="text" prepend-icon="mdi-refresh" :loading="logLoading" @click="loadLogs(logPage)">รีเฟรช</v-btn></div><v-table><thead><tr><th>วันเวลา</th><th>ผู้ดำเนินการ</th><th>การดำเนินการ</th><th>รายละเอียด</th></tr></thead><tbody><tr v-for="l in logs" :key="l._id"><td>{{new Date(l.createdAt).toLocaleString('th-TH')}}</td><td>{{l.actor?.name||'ผู้ใช้ที่ถูกลบ'}}</td><td>{{l.action==='trip.updated'?'แก้ไขข้อมูลทริป':(actionLabels[l.action]||l.action)}}</td><td>{{l.action==='trip.updated'?((l.details?.before?.name||'')+' → '+(l.details?.after?.name||'')): (l.details?.title||l.details?.name||l.details?.bank||'-')}} <span v-if="l.details?.amountCents!=null">· ฿{{thb(l.details.amountCents)}}</span></td></tr><tr v-if="!logs.length"><td colspan="4" class="text-center pa-6">ยังไม่มีประวัติ</td></tr></tbody></v-table><div class="d-flex justify-end align-center ga-2 mt-3"><span class="text-caption">{{logTotal}} รายการ · หน้า {{logPage}}</span><v-btn size="small" :disabled="logPage<=1" @click="loadLogs(logPage-1)">ก่อนหน้า</v-btn><v-btn size="small" :disabled="logPage*30>=logTotal" @click="loadLogs(logPage+1)">ถัดไป</v-btn></div></div></v-window-item></v-window></v-card></template>
<v-dialog v-model="editTripDialog" max-width="540"><v-card class="pa-5"><div class="d-flex align-center ga-2 mb-4"><v-icon color="primary">mdi-pencil-outline</v-icon><h3 class="text-h6">แก้ไขข้อมูลทริป</h3></div><v-alert v-if="editTripError" type="error" variant="tonal" class="mb-3">{{editTripError}}</v-alert><v-form @submit.prevent="saveTrip"><v-text-field v-model="tripEdit.name" label="ชื่อทริป" placeholder="เช่น หาดใหญ่" maxlength="120" counter required autofocus/><v-textarea v-model="tripEdit.description" label="รายละเอียดทริป" placeholder="เช่น ทริปหาดใหญ่ 3–8 พฤศจิกายน 2569" maxlength="500" counter rows="3" auto-grow/><p class="text-caption muted mb-4">แก้ไขได้เฉพาะเจ้าของทริป และมีการบันทึกประวัติการเปลี่ยนแปลง</p><div class="d-flex justify-end ga-2"><v-btn variant="text" :disabled="editTripBusy" @click="editTripDialog=false">ยกเลิก</v-btn><v-btn color="primary" type="submit" :loading="editTripBusy">บันทึกการแก้ไข</v-btn></div></v-form></v-card></v-dialog>
<v-dialog v-model="dialog" max-width="620"><v-card class="pa-5"><h3 class="text-h6 mb-4">เพิ่มค่าใช้จ่าย</h3><v-alert v-if="error" type="error" variant="tonal" class="mb-3">{{error}}</v-alert><v-form @submit.prevent="saveExpense"><v-text-field v-model="form.title" label="รายการ เช่น ค่าอาหาร / ค่าน้ำมัน" required/><v-row><v-col cols="6"><v-text-field v-model="dateInput" label="วันที่ (วัน/เดือน/ปี)" placeholder="03/11/2026" hint="รูปแบบ DD/MM/YYYY (ค.ศ.)" persistent-hint prepend-inner-icon="mdi-calendar" required/></v-col><v-col cols="6"><v-text-field v-model="form.amount" label="จำนวนเงิน (บาท)" type="number" min="0.01" step="0.01" prefix="฿" required/></v-col></v-row><v-select v-model="form.paidBy" :items="members" item-title="name" item-value="_id" label="ใครเป็นผู้จ่าย"/><v-radio-group v-model="mode" inline><v-radio label="หารเท่ากัน" value="equal"/><v-radio label="กำหนดยอดเอง" value="custom"/></v-radio-group><div class="d-flex align-center flex-wrap ga-2 mb-2"><strong>เลือกคนที่ร่วมรับผิดชอบ</strong><v-spacer/><v-btn size="small" variant="text" @click="form.participants=members.map(m=>m._id)">เลือกทั้งหมด</v-btn><v-btn size="small" variant="text" @click="form.participants=[]">ล้างทั้งหมด</v-btn></div><v-alert v-if="mode==='equal'&&form.participants.length&&amountValid(form.amount)" density="compact" variant="tonal" color="primary" class="mb-3">{{form.participants.length}} คน · เฉลี่ยประมาณ ฿{{thb(Math.round(cents(form.amount)/form.participants.length))}} ต่อคน</v-alert><div v-for="m in members" :key="m._id" class="d-flex align-center ga-3"><v-checkbox v-model="form.participants" :label="m.name" :value="m._id" hide-details class="flex-grow-1"/><v-text-field v-if="mode==='custom'&&form.participants.includes(m._id)" v-model="form.custom[m._id]" type="number" step="0.01" min="0" prefix="฿" density="compact" style="max-width:170px"/></div><div class="d-flex justify-end ga-2 mt-5"><v-btn variant="text" @click="dialog=false">ยกเลิก</v-btn><v-btn type="submit" color="primary" :loading="busy">บันทึก</v-btn></div></v-form></v-card></v-dialog>
<v-dialog v-model="bankDialog" max-width="480"><v-card class="pa-5"><h3 class="text-h6 mb-4">{{bankEditId?'แก้ไข':'เพิ่ม'}}บัญชีธนาคารของฉัน</h3><v-form @submit.prevent="saveBank"><v-text-field v-model="bankForm.bank" label="ชื่อธนาคาร" maxlength="80" required/><v-text-field v-model="bankForm.accountName" label="ชื่อบัญชี" maxlength="120" required/><v-text-field v-model="bankForm.accountNumber" label="หมายเลขบัญชี" maxlength="30" required hint="ใช้ตัวเลข ไม่ต้องใส่ขีด" persistent-hint/><v-checkbox v-model="bankForm.isDefault" label="ใช้เป็นบัญชีหลักสำหรับรับเงิน"/><p class="text-caption muted mb-3">สมาชิกในทริปเดียวกันจะเห็นเลขบัญชีนี้เพื่อโอนเงิน</p><div class="d-flex justify-end ga-2"><v-btn variant="text" @click="bankDialog=false">ยกเลิก</v-btn><v-btn color="primary" type="submit" :loading="busy">บันทึก</v-btn></div></v-form></v-card></v-dialog><v-dialog v-model="payDialog" max-width="450"><v-card class="pa-5"><h3 class="text-h6 mb-4">บันทึกการชำระเงิน</h3><p class="mb-2">{{names[pay.from]}} → {{names[pay.to]}}</p><v-alert v-if="primaryAccount(pay.to)" variant="tonal" color="primary" class="mb-4">บัญชีรับเงิน: {{primaryAccount(pay.to).bank}}<div>{{primaryAccount(pay.to).accountName}} · {{primaryAccount(pay.to).accountNumber}}</div></v-alert><v-alert v-else type="warning" variant="tonal" class="mb-4">ผู้รับยังไม่ได้เพิ่มบัญชีธนาคาร</v-alert><v-form @submit.prevent="savePayment"><v-text-field v-model="pay.amount" label="จำนวนเงินที่โอนจริง (บาท)" type="number" step="0.01" min="0.01" required/><v-text-field v-model="pay.note" label="หมายเหตุ (ไม่บังคับ)"/><v-btn type="submit" block color="primary" :loading="busy">ยืนยันบันทึกโอน</v-btn></v-form></v-card></v-dialog></v-container></template>

